const item = $input.first().json;
const body = item.body || item;

const cuil = body.cuil;
const action = body.action;
const monodroga = body.monodroga;
const desde = body.desde;
const hasta = body.hasta;
const venceEnDias = body.vence_en_dias;

if (!cuil || !/^\d{11}$/.test(String(cuil))) {
  return [{ json: { error: 'CUIL invalido. Debe tener 11 digitos numericos.' } }];
}

if (!action) {
  return [{ json: { error: 'Falta la accion. Use: autorizaciones, cronicidad, o exists.' } }];
}

let apiUrl = '';
const base = 'https://asesores-api.osadef.org.ar';

if (['autorizaciones','autorizacion','medicamentos'].includes(action)) {
  apiUrl = `${base}/autorizaciones?cuil=${cuil}`;
  if (monodroga) apiUrl += `&monodroga=${encodeURIComponent(monodroga)}`;
  if (desde) apiUrl += `&desde=${encodeURIComponent(desde)}`;
  if (hasta) apiUrl += `&hasta=${encodeURIComponent(hasta)}`;
} else if (['cronicidad','cronico','tratamiento','patologia'].includes(action)) {
  apiUrl = `${base}/cronicidad?cuil=${cuil}`;
  if (monodroga) apiUrl += `&monodroga=${encodeURIComponent(monodroga)}`;
  if (venceEnDias) apiUrl += `&vence_en_dias=${encodeURIComponent(venceEnDias)}`;
} else if (['exists','validar','afiliado'].includes(action)) {
  apiUrl = `${base}/afiliados/exists?cuil=${cuil}`;
} else {
  return [{ json: { error: `Accion '${action}' no reconocida. Use: autorizaciones, cronicidad, o exists.` } }];
}

return [{ json: { apiUrl, cuil, action } }];
